// ===================== VALIDATE PDF LINKS =====================
private string ValidatePdfLinks(string html)
{
    if (string.IsNullOrEmpty(html))
        return html;

    try
    {
        var doc = new HtmlDocument();
        doc.LoadHtml(html);

        var nodes = doc.DocumentNode.SelectNodes("//iframe[@src] | //frame[@src]");
        if (nodes == null)
            return html;

        bool modified = false;
        foreach (var node in nodes)
        {
            string src = node.GetAttributeValue("src", "");
            if (string.IsNullOrEmpty(src))
                continue;

            // Bo qua link tuyet doi (http/https)
            if (src.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
                src.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
                continue;

            // Chi xu ly link PDF
            if (!src.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase))
                continue;

            // Kiem tra file vat ly tren server
            string physicalPath = Server.MapPath(src);
            if (!File.Exists(physicalPath))
            {
                string notice = "<div class=\"pdf-not-found\" style=\"padding:12px;background:#fff3f3;border:1px solid #ffcccc;border-radius:5px;color:#cc0000;text-align:center;margin:10px 0;\">File PDF khong ton tai</div>";
                var newNode = HtmlNode.CreateNode(notice);
                node.ParentNode.ReplaceChild(newNode, node);
                modified = true;
            }
        }

        if (modified)
            return doc.DocumentNode.InnerHtml;

        return html;
    }
    catch
    {
        return html;
    }
}

